q_pdd_194", "q": {"ru": "Когда можно вернуться в свою полосу после обгона?", "kk": "Басып озғаннан кейін өз жолағына қашан оралуға болады?"}, "options": [{"ru": "Когда не создашь помеху обогнанному", "kk": "Басып озғанға кедергі туғызбағанда"}, {"ru": "Сразу", "kk": "Бірден"}, {"ru": "Через 1 км", "kk": "1 км кейін"}], "correct": 0, "explain": {"ru": "Возвращаются, не создавая помехи.", "kk": "Кедергі туғызбай оралады."}}, {"id": "q_pdd_195", "q": {"ru": "Разрешён ли обгон на пешеходном переходе?", "kk": "Жаяу өткелде басып озуға рұқсат па?"}, "options": [{"ru": "Да", "kk": "Иә"}, {"ru": "Только если нет пешеходов", "kk": "Тек жаяу жүргіншілер болмаса"}, {"ru": "Нет", "kk": "Жоқ"}], "correct": 2, "explain": {"ru": "Обгон на переходе запрещён.", "kk": "Өткелде басып озуға тыйым."}}, {"id": "q_pdd_196", "q": {"ru": "Можно ли обгонять, если впереди ТС включило левый поворотник?", "kk": "Алдағы көлік сол бұрылыс сигналын қосса басып озуға бола ма?"}, "options": [{"ru": "Да", "kk": "Иә"}, {"ru": "Нет", "kk": "Жоқ"}, {"ru": "Только справа", "kk": "Тек оң жақтан"}], "correct": 1, "explain": {"ru": "Нельзя обгонять, если впереди подали сигнал налево.", "kk": "Алда солға сигнал берсе басып озуға болмайды."}}, {"id": "q_pdd_197", "q": {"ru": "Как двигаться в плотном потоке?", "kk": "Тығыз ағында қалай жүру керек?"}, "options": [{"ru": "Держать дистанцию и не дёргаться", "kk": "Арақашықтықты сақтап, жұлқынбау"}, {"ru": "Резко перестраиваться", "kk": "Күрт қатар ауыстыру"}, {"ru": "Ехать по обочине", "kk": "Жол жиегімен жүру"}], "correct": 0, "explain": {"ru": "В потоке важны дистанция и плавность.", "kk": "Ағында арақашықтық пен жұмсақтық маңызды."}}, {"id": "q_pdd_198", "q": {"ru": "Что делать, если вас обгоняют?", "kk": "Сізді басып озса не істеу керек?"}, "options": [{"ru": "Выехать на встречную", "kk": "Қарсы жолаққа шығу"}, {"ru": "Не препятствовать обгону", "kk": "Басып озуға кедергі жасамау"}, {"ru": "Ускориться", "kk": "Жылдамдау"}], "correct": 1, "explain": {"ru": "Не