: "Да, если это крайняя левая и нет запрета", "kk": "Иә, ең сол болса және тыйым болмаса"}], "correct": 2, "explain": {"ru": "Для левого поворота занимают крайнюю левую.", "kk": "Солға бұрылу үшін ең сол жолақты алады."}}, {"id": "q_pdd_204", "q": {"ru": "Как правильно остановиться у тротуара?", "kk": "Жол жиегінде қалай дұрыс тоқтау керек?"}, "options": [{"ru": "Поперёк", "kk": "Көлденең"}, {"ru": "Параллельно, близко к бордюру, не мешая", "kk": "Параллель, бордюрге жақын, кедергісіз"}, {"ru": "Далеко от бордюра", "kk": "Бордюрден алыс"}], "correct": 1, "explain": {"ru": "Остановка параллельно бордюру.", "kk": "Бордюрге параллель тоқтау."}}, {"id": "q_pdd_205", "q": {"ru": "Разрешена ли стоянка на мосту?", "kk": "Көпірде тұраққа рұқсат па?"}, "options": [{"ru": "Только легковым", "kk": "Тек жеңіл көліктерге"}, {"ru": "Да", "kk": "Иә"}, {"ru": "Нет", "kk": "Жоқ"}], "correct": 2, "explain": {"ru": "Стоянка на мосту запрещена.", "kk": "Көпірде тұраққа тыйым."}}, {"id": "q_pdd_206", "q": {"ru": "Можно ли останавливаться на эстакаде?", "kk": "Эстакадада тоқтауға бола ма?"}, "options": [{"ru": "Только днём", "kk": "Тек күндіз"}, {"ru": "Нет", "kk": "Жоқ"}, {"ru": "Да", "kk": "Иә"}], "correct": 1, "explain": {"ru": "Остановка на эстакаде запрещена.", "kk": "Эстакадада тоқтауға тыйым."}}, {"id": "q_pdd_207", "q": {"ru": "Что такое «вынужденная остановка»?", "kk": "«Мәжбүрлі тоқтау» деген не?"}, "options": [{"ru": "Остановка из-за неисправности или препятствия", "kk": "Ақау немесе кедергі салдарынан тоқтау"}, {"ru": "Парковка", "kk": "Тұрақ"}, {"ru": "Остановка по желанию", "kk": "Қалау бойынша тоқтау"}], "correct": 0, "explain": {"ru": "Вынужденная — из-за поломки или опасности.", "kk": "Мәжбүрлі — ақау немесе қауіп салдарынан."}}, {"id": "q_pdd_208", "q": {"ru": "Как обозначить вынужденную остановку?", "kk": "Мәжбүрлі тоқтауды қалай белгілеу керек?"}, "options": [{"ru": "Только гудок", "kk": "Тек сигнал"}, {"ru": "Аварийка и знак аварийной остановки", "kk": "Апат сигналы және апат тоқтау белгісі"}, {"ru": "Никак", "kk": "Ешқалай"}], "correct": 1, "explain": {"ru": "Нужны аварийка и знак.", "kk": "Апат сигналы мен белгі керек."}}, {"id": "q_pdd_209", "q": {"ru": "Разрешён ли обгон в тоннеле?", "kk": "Туннельде басып озуға рұқсат па?"}, "options": [{"ru": "Нет", "kk": "Жоқ"}, {"ru": "Только ночью", "kk": "Тек түнде"}, {"ru": "Да", "kk": "Иә"}], "correct": 0, "explain": {"ru": "Обгон в тоннеле запрещён.", "kk": "Туннельде басып озуға тыйым."}}, {"id": "q_pdd_210", "q": {"ru": "Как двигаться при буксировке на гибкой сцепке?", "kk": "Икемді ілініспен сүйрегенде қалай жүру керек?"}, "options": [{"ru": "С большей скоростью", "kk": "Жоғары жылдамдықпен"}, {"ru": "С ограниченной скоростью, с обозначением", "kk": "Шектелген жылдамдықпен, белгілеумен"}, {"ru": "Без сигналов", "kk": "Сигналсыз"}], "correct": 1, "explain": {"ru": "Буксировка — по правилам, с ограничениями.", "kk": "Сүйреу — ереже бойынша, шектеулермен."}}, {"id": "q_pdd_211", "q": {"ru": "Кто имеет преимущество при повороте направо и пешеходе на переходе?", "kk": "Оңға бұрылғанда және өткелдегі жаяу жүргіншіде кімнің басымдығы бар?"}, "options": [{"ru": "Пешеход", "kk": "Жаяу жүргінші"}, {"ru": "Кто быстрее", "kk": "Кім жылдам"}, {"ru": "Водитель", "kk": "Жүргізуші"}], "correct": 0, "explain": {"ru": "Пешеход на переходе имеет преимущество.", "kk": "Өткелдегі жаяу жүргіншінің басымдығы бар."}}, {"id": "q_pdd_212", "q": {"ru": "Как проезжать перекрёсток, если главная меняет направление?", "kk": "Басты жол бағытын өзгертсе қиылысты қалай өту керек?"}, "options": [{"ru": "Всегда уступать", "kk": "Әрқашан жол беру"}, {"ru": "Всегда прямо", "kk": "Әрқашан тіке"}, {"ru": "По табличке направления главной", "kk": "Басты жол бағытының тақтайшасы бойынша"}], "correct": 2, "explain": {"ru": "Смотрят на схему главной дороги.", "kk": "Басты жол схемасына қарайды."}}, {"id": "q_pdd_213", "q": {"ru": "Можно ли останавливаться на перекрёстке при зелёном, если впереди затор?", "kk": "Алда кептеліс болса жасылда қиылыста тоқтауға бола ма?"}, "options": [{"ru": "Нет", "kk": "Жоқ"}, {"ru": "Да", "kk": "Иә"}, {"ru": "Только налево", "kk": "Тек солға"}], "correct": 0, "explain": {"ru": "Нельзя выезжать, если застрянешь на перекрёстке.", "kk": "Қиылыста тұрып қалсаң шығуға болмайды."}}, {"id": "q_pdd_214", "q": {"ru": "Что означает знак «Пересечение равнозначных дорог»?", "kk": "«Тең жолдардың қиылысы» белгісі нені білдіреді?"}, "options": [{"ru": "Стоп", "kk": "Тоқта"}, {"ru": "Главная дорога", "kk": "Басты жол"}, {"ru": "Равнозначный перекрёсток, помеха справа", "kk": "Тең қиылыс, оң кедергі"}], "correct": 2, "explain": {"ru": "На равнозначных — помеха справа.", "kk": "Тең жолдарда — оң кедергі."}}, {"id": "q_pdd_215", "q": {"ru": "Как повернуть налево, если есть трамвайные пути попутного направления?", "kk": "Бір бағыттағы трамвай жолдары болса солға қалай бұрылу керек?"}, "options": [{"ru": "Запрещено", "kk": "Тыйым"}, {"ru": "По правилам, не создавая помех трамваю", "kk": "Ереже бойынша, трамвайға кедергі туғызбай"}, {"ru": "Всегда по путям", "kk": "Әрқашан жолдармен"}], "correct": 1, "explain": {"ru": "Поворот с учётом трамвая.", "kk": "Трамвайды ескере отырып бұрылу."}}, {"id": "q_pdd_216", "q": {"ru": "Кто проедет первым: вы по главной, встречный по второстепенной?", "kk": "Сіз басты жолда, қарсы қосалқыда: кім бірінші өтеді?"}, "options": [{"ru": "Встречный", "kk": "Қарсы"}, {"ru": "Одновременно", "kk": "Бір уақытта"}, {"ru": "Вы", "kk": "Сіз"}], "correct": 2, "explain": {"ru": "На главной — преимущество.", "kk": "Басты жолда — басымдық."}}, {"id": "q_pdd_217", "q": {"ru": "Что делать, если на перекрёстке нет знаков и светофора?", "kk": "Қиылыста белгі мен бағдаршам болмаса не істеу керек?"}, "options": [{"ru": "Уступить помехе справа", "kk": "Оң кедергіге жол беру"}, {"ru": "Остановиться навсегда", "kk": "Мәңгі тоқтау"}, {"ru": "Ехать первым", "kk": "Бірінші жүру"}], "correct": 0, "explain": {"ru": "Равнозначный — помеха справа.", "kk": "Тең — оң кедергі."}}, {"id": "q_pdd_218", "q": {"ru": "Разрешён ли разворот на перекрёстке по главной?", "kk": "Басты жолдағы қиылыста бұрылуға рұқсат па?"}, "options": [{"ru": "Никогда", "kk": "Ешқашан"}, {"ru": "Да, если нет запрета", "kk": "Иә, тыйым болмаса"}, {"ru": "Только ночью", "kk": "Тек түнде"}], "correct": 1, "explain": {"ru": "Разворот возможен при отсутствии запрета.", "kk": "Тыйым болмаса бұрылу мүмкін."}}, {"id": "q_pdd_219", "q": {"ru": "Как действовать при знаке «Движение прямо или направо»?", "kk": "«Тіке немесе оңға жүру» белгісінде қалай әрекет ету керек?"}, "options": [{"ru": "Только прямо или направо", "kk": "Тек тіке немесе оңға"}, {"ru": "Можно налево", "kk": "Солға болады"}, {"ru": "Только налево", "kk": "Тек солға"}], "correct": 0, "explain": {"ru": "Предписывает прямо или направо.", "kk": "Тіке немесе оңға талап етеді."}}, {"id": "q_pdd_220", "q": {"ru": "Что означает красный сигнал для пешехода?", "kk": "Жаяу жүргіншіге қызыл сигнал нені білдіреді?"}, "options": [{"ru": "Бегите", "kk": "Жүгіріңіз"}, {"ru": "Переход запрещён", "kk": "Өтуге тыйым"}, {"ru": "Можно идти", "kk": "Жүруге болады"}], "correct": 1, "explain": {"ru": "Красный пешеходу — стоять.", "kk": "Жаяу жүргіншіге қызыл — тұру."}}, {"id": "q_pdd_221", "q": {"ru": "Можно ли начать переход на мигающий зелёный пешеходный?", "kk": "Жыпылықтаған жасыл жаяу сигналда өтуді бастауға бола ма?"}, "options": [{"ru": "Лучше не начинать, если не успеете", "kk": "Үлгермесеңіз бастамағаныңыз дұрыс"}, {"ru": "Обязательно бежать", "kk": "Міндетті түрде жүгіру"}, {"ru": "Да, спокойно", "kk": "Иә, сабырлы"}], "correct": 0, "explain": {"ru": "Мигающий — завершайте, не начинайте.", "kk": "Жыпылықтау — аяқтаңыз, бастамаңыз."}}, {"id": "q_pdd_222", "q": {"ru": "Кто уступает при выезде из двора?", "kk": "Ауладан шыққанда кім жол береді?"}, "options": [{"ru": "Пешеход во дворе", "kk": "Ауладағы жаяу жүргінші"}, {"ru": "Выезжающий из двора", "kk": "Ауладан шығатын"}, {"ru": "Движущиеся по дороге", "kk": "Жолмен жүріп жатқандар"}], "correct": 1, "explain": {"ru": "Выезжающий из двора уступает.", "kk": "Ауладан шығатын жол береді."}}, {"id": "q_pdd_223", "q": {"ru": "Как проезжать перекрёсток с работающим жёлтым мигающим и знаком «Главная»?", "kk": "Жұмыс істеп тұрған сары жыпылықтау және «Басты» белгісі бар қиылысты қалай өту керек?"}, "options": [{"ru": "По знаку главной", "kk": "Басты белгі бойынша"}, {"ru": "По помехе справа всегда", "kk": "Әрқашан оң кедергі бойынша"}, {"ru": "Все уступают", "kk": "Барлығы жол береді"}], "correct": 0, "explain": {"ru": "Знак приоритета действует.", "kk": "Басымдық белгісі әрекет етеді."}}, {"id": "q_pdd_224", "q": {"ru": "Разрешена ли остановка ближе 15 м от остановки маршрутного ТС?", "kk": "Бағыттық көлік аялдамасынан 15 м жақын тоқтауға рұқсат па?"}, "options": [{"ru": "Только ночью", "kk": "Тек түнде"}, {"ru": "Нет", "kk": "Жоқ"}, {"ru": "Да", "kk": "Иә"}], "correct": 1, "explain": {"ru": "Ближе 15 м от остановки — нельзя.", "kk": "Аялдамадан 15 м жақын — болмайды."}}, {"id": "q_pdd_225", "q": {"ru": "Что означает знак «Уступите дорогу» с табличкой расстояния?", "kk": "Қашықтық тақтайшасы бар «Жол беріңіз» белгісі нені білдіреді?"}, "options": [{"ru": "Уступить через указанное расстояние", "kk": "Көрсетілген қашықтықтан кейін жол беру"}, {"ru": "Главная", "kk": "Басты"}, {"ru": "Сразу стоп", "kk": "Бірден тоқта"}], "correct": 0, "explain": {"ru": "Табличка показывает, через сколько метров уступать.", "kk": "Тақтайша неше метрден кейін жол беретінін көрсетеді."}}, {"id": "q_pdd_226", "q": {"ru": "Как повернуть направо, если правая полоса занята?", "kk": "Оң жолақ бос болмаса оңға қалай бұрылу керек?"}, "options": [{"ru": "Через двойную сплошную", "kk": "Қос тұтас арқылы"}, {"ru": "С левой", "kk": "Сол жақтан"}, {"ru": "Дождаться и повернуть с правой", "kk": "Күтіп, оң жақтан бұрылу"}], "correct": 2, "explain": {"ru": "Правый поворот только с правой полосы.", "kk": "Оң бұрылыс тек оң жолақтан."}}, {"id": "q_pdd_227", "q": {"ru": "Что делать, если регулировщик стоит боком к вам, руки в стороны?", "kk": "Реттеуші сізге бүйірімен тұрса, қолдары екі жаққа болса не істеу керек?"}, "options": [{"ru": "Стоп", "kk": "Тоқта"}, {"ru": "Движение разрешено прямо и направо", "kk": "Тіке және оңға жүру рұқсат"}, {"ru": "Только налево", "kk": "Тек солға"}], "correct": 1, "explain": {"ru": "Боком, руки в стороны — можно прямо и направо.", "kk": "Бүйірімен, қолдары екі жаққа — тіке және оңға болады."}}, {"id": "q_pdd_228", "q": {"ru": "Что означает жест регулировщика «рука вперёд» для встречных?", "kk": "Реттеушінің «қол алға» қимылы қарсы келетіндерге нені білдіреді?"}, "options": [{"ru": "Им стоп", "kk": "Оларға тоқта"}, {"ru": "Разворот", "kk": "Бұрылу"}, {"ru": "Им можно", "kk": "Оларға болады"}], "correct": 0, "explain": {"ru": "Со стороны груди — стоп.", "kk": "Кеуде жағынан — тоқта."}}, {"id": "q_pdd_229", "q": {"ru": "Можно ли въезжать на перекрёсток на жёлтый, если не успеваете остановиться?", "kk": "Тоқтауға үлгермесеңіз сарыға қиылысқа кіруге бола ма?"}, "options": [{"ru": "Никогда", "kk": "Ешқашан"}, {"ru": "Да, если остановка опасна", "kk": "Иә, тоқтау қауіпті болса"}, {"ru": "Только налево", "kk": "Тек солға"}], "correct": 1, "explain": {"ru": "Если безопасно остановиться нельзя — можно проехать.", "kk": "Қауіпсіз тоқтау мүмкін болмаса — өтуге болады."}}, {"id": "q_pdd_230", "q": {"ru": "Как проезжать перекрёсток с круговым движением при знаке «Главная дорога» на въезде?", "kk": "Кіреберісте «Басты жол» белгісі бар айналма қиылысты қалай өту керек?"}, "options": [{"ru": "Стоп всегда", "kk": "Әрқашан тоқта"}, {"ru": "Всегда уступать кругу", "kk": "Әрқашан шеңберге жол беру"}, {"ru": "Въезжающий имеет преимущество", "kk": "Кіретіннің басымдығы бар"}], "correct": 2, "explain": {"ru": "Если на въезде главная — преимущество у въезжающего.", "kk": "Кіреберісте басты болса — кіретіннің басымдығы."}}, {"id": "q_pdd_231", "q": {"ru": "Можно ли учиться вождению на автомагистрали?", "kk": "Автомагистральда жүргізуді үйренуге бола ма?"}, "options": [{"ru": "Да", "kk": "Иә"}, {"ru": "Нет", "kk": "Жоқ"}, {"ru": "Только с инструктором ночью", "kk": "Тек түнде нұсқаушымен"}], "correct": 1, "explain": {"ru": "Учебная езда на автомагистрали запрещена.", "kk": "Автомагистральда оқу жүрісіне тыйым."}}, {"id": "q_pdd_232", "q": {"ru": "Разрешён ли въезд мопедов на автомагистраль?", "kk": "Автомагистральға мопедтерге кіруге рұқсат па?"}, "options": [{"ru": "Только днём", "kk": "Тек күндіз"}, {"ru": "Да", "kk": "Иә"}, {"ru": "Нет", "kk": "Жоқ"}], "correct": 2, "explain": {"ru": "Мопедам на автомагистраль нельзя.", "kk": "Мопедтерге автомагистральға болмайды."}}, {"id": "q_pdd_233", "q": {"ru": "Какая максимальная скорость для грузовика вне населённого пункта?", "kk": "Елді мекеннен тыс жүк көлігінің ең жоғары жылдамдығы қандай?"}, "options": [{"ru": "90 км/ч", "kk": "90 км/сағ"}, {"ru": "70 км/ч обычно", "kk": "Әдетте 70 км/сағ"}, {"ru": "110 км/ч", "kk": "110 км/сағ"}], "correct": 1, "explain": {"ru": "Для грузовиков лимит ниже, обычно 70.", "kk": "Жүк көліктеріне шек төмен, әдетте 70."}}, {"id": "q_pdd_234", "q": {"ru": "Что грозит за езду без страховки в РК?", "kk": "ҚР-да сақтандырусыз жүргені үшін не күтеді?"}, "options": [{"ru": "Штраф", "kk": "Айыппұл"}, {"ru": "Ничего", "kk": "Ештеңе"}, {"ru": "Только предупреждение", "kk": "Тек ескерту"}], "correct": 0, "explain": {"ru": "Отсутствие ОГПО — штраф.", "kk": "МҚІА болмауы — айыппұл."}}, {"id": "q_pdd_235", "q": {"ru": "Можно ли передавать руль человеку без прав?", "kk": "Рөлді куәліксіз адамға беруге бола ма?"}, "options": [{"ru": "Только на пустой дороге", "kk": "Тек бос жолда"}, {"ru": "Нет", "kk": "Жоқ"}, {"ru": "Да", "kk": "Иә"}], "correct": 1, "explain": {"ru": "Передача управления лицу без прав запрещена.", "kk": "Куәліксіз адамға басқаруды беруге тыйым."}}, {"id": "q_pdd_236", "q": {"ru": "Что обязан сделать водитель при ДТП с пострадавшими?", "kk": "Зардап шеккендер бар ЖКО кезінде жүргізуші не істеуге міндетті?"}, "options": [{"ru": "Только сфотографировать", "kk": "Тек суретке түсіру"}, {"ru": "Уехать", "kk": "Кетіп қалу"}, {"ru": "Вызвать скорую и полицию, оказать помощь", "kk": "Жедел жәрдем мен полицияны шақырып, көмек көрсету"}], "correct": 2, "explain": {"ru": "При пострадавших — помощь и вызов служб.", "kk": "Зардап шеккендер болса — көмек және қызметтерді шақыру."}}, {"id": "q_pdd_237", "q": {"ru": "Как действовать при сильном дожде?", "kk": "Қатты жаңбырда қалай әрекет ету керек?"}, "options": [{"ru": "Выключить дворники", "kk": "Шыны тазалағыштарды өшіру"}, {"ru": "Снизить скорость, включить свет, увеличить дистанцию", "kk": "Жылдамдықты төмендетіп, жарықты қосып, арақашықтықты ұлғайту"}, {"ru": "Ехать быстро", "kk": "Жылдам жүру"}], "correct": 1, "explain": {"ru": "В дождь — осторожность и свет.", "kk": "Жаңбырда — сақтық және жарық."}}, {"id": "q_pdd_238", "q": {"ru": "Что такое аквапланирование?", "kk": "Аквапланирование деген не?"}, "options": [{"ru": "Нормальное сцепление", "kk": "Қалыпты ілінісу"}, {"ru": "Торможение", "kk": "Тежеу"}, {"ru": "Потеря сцепления на воде", "kk": "Су үстінде ілінісуді жоғалту"}], "correct": 2, "explain": {"ru": "На воде шины теряют контакт с дорогой.", "kk": "Су үстінде дөңгелектер жолмен байланысын жоғалтады."}}, {"id": "q_pdd_239", "q": {"ru": "Как избежать аквапланирования?", "kk": "Аквапланированиеден қалай аулақ болу керек?"}, "options": [{"ru": "Снизить скорость на мокрой дороге", "kk": "Ылғал жолда жылдамдықты төмендету"}, {"ru": "Ехать быстрее", "kk": "Жылдамырақ жүру"}, {"ru": "Резко тормозить", "kk": "Күрт тежеу"}], "correct": 0, "explain": {"ru": "Ниже скорость на воде.", "kk": "Су үстінде төмен жылдамдық."}}, {"id": "q_pdd_240", "q": {"ru": "Разрешена ли езда с треснутым лобовым стеклом в зоне обзора?", "kk": "Көру аймағында жарылған алдыңғы әйнекпен жүруге рұқсат па?"}, "options": [{"ru": "Да", "kk": "Иә"}, {"ru": "Только ночью", "kk": "Тек түнде"}, {"ru": "Нет, если мешает обзору", "kk": "Жоқ, көруге кедергі болса"}], "correct": 2, "explain": {"ru": "Стекло не должно мешать обзору.", "kk": "Әйнек көруге кедергі жасамауы керек."}}, {"id": "q_pdd_241", "q": {"ru": "Что обязан проверить водитель перед выездом?", "kk": "Жолға шықпас бұрын жүргізуші не тексеруге міндетті?"}, "options": [{"ru": "Только топливо", "kk": "Тек отын"}, {"ru": "Техническое состояние: свет, тормоза, шины", "kk": "Техникалық жағдай: жарық, тежегіш, дөңгелек"}, {"ru": "Ничего", "kk": "Ештеңе"}], "correct": 1, "explain": {"ru": "Перед выездом проверяют исправность.", "kk": "Жолға шықпас бұрын ақаусыздықты тексереді."}}, {"id": "q_pdd_242", "q": {"ru": "Можно ли ехать с неработающей фарой ночью?", "kk": "Түнде жұмыс істемейтін фарамен жүруге бола ма?"}, "options": [{"ru": "Только в городе", "kk": "Тек қалада"}, {"ru": "Да", "kk": "Иә"}, {"ru": "Нет", "kk": "Жоқ"}], "correct": 2, "explain": {"ru": "Ночью обе фары должны работать.", "kk": "Түнде екі фара да жұмыс істеуі керек."}}, {"id": "q_pdd_243", "q": {"ru": "Что означает знак «Ограничение ширины»?", "kk": "«Ені шектеуі» белгісі нені білдіреді?"}, "options": [{"ru": "Любая ширина", "kk": "Кез келген ен"}, {"ru": "Запрещён проезд шире указанного", "kk": "Көрсетілгеннен кең көліктерге өтуге тыйым"}, {"ru": "Рекомендация", "kk": "Ұсыныс"}], "correct": 1, "explain": {"ru": "Ограничивает ширину ТС.", "kk": "Көлік енін шектейді."}}, {"id": "q_pdd_244", "q": {"ru": "Как проехать ж/д переезд без шлагбаума?", "kk": "Шлагбаумсыз теміржол өткелін қалай өту керек?"}, "options": [{"ru": "Остановиться на путях", "kk": "Жолдарда тоқтау"}, {"ru": "Обгоняя", "kk": "Басып озып"}, {"ru": "Не останавливаясь на путях, убедившись в отсутствии поезда", "kk": "Пойыз жоқ екеніне көз жеткізіп, жолдарда тоқтамай"}], "correct": 2, "explain": {"ru": "Убедиться, что поезда нет, и проехать.", "kk": "Пойыз жоқ екеніне көз жеткізіп, өту."}}, {"id": "q_pdd_245", "q": {"ru": "Что делать, если поезд приближается, а вы на переезде?", "kk": "Сіз өткелде болсаңыз және пойыз жақындаса не істеу керек?"}, "options": [{"ru": "Сигналить поезду", "kk": "Пойызға сигнал беру"}, {"ru": "Немедленно покинуть переезд", "kk": "Өткелді дереу тастап кету"}, {"ru": "Ждать", "kk": "Күту"}], "correct": 1, "explain": {"ru": "Нужно срочно освободить переезд.", "kk": "Өткелді шұғыл босату керек."}}, {"id": "q_pdd_246", "q": {"ru": "Разрешена ли стоянка ближе 50 м от ж/д переезда?", "kk": "Теміржол өткелінен 50 м жақын тұраққа рұқсат па?"}, "options": [{"ru": "Нет", "kk": "Жоқ"}, {"ru": "Только ночью", "kk": "Тек түнде"}, {"ru": "Да", "kk": "Иә"}], "correct": 0, "explain": {"ru": "Ближе 50 м от переезда стоянка запрещена.", "kk": "Өткелден 50 м жақын тұраққа тыйым."}}, {"id": "q_pdd_247", "q": {"ru": "Как действовать в жилой зоне ночью?", "kk": "Түнде тұрғын аймақта қалай әрекет ету керек?"}, "options": [{"ru": "Сигналить", "kk": "Сигнал беру"}, {"ru": "Ехать быстро", "kk": "Жылдам жүру"}, {"ru": "Тихо, низкая скорость, уступать пешеходам", "kk": "Тыныш, төмен жылдамдық, жаяу жүргіншілерге жол беру"}], "correct": 2, "explain": {"ru": "В жилой зоне — тишина и приоритет пешеходов.", "kk": "Тұрғын аймақта — тыныштық және жаяу жүргіншілердің басымдығы."}}, {"id": "q_pdd_248", "q": {"ru": "Можно ли сквозной проезд через двор?", "kk": "Аула арқылы өтпелі жүруге бола ма?"}, "options": [{"ru": "Нет, сквозной проезд запрещён", "kk": "Жоқ, өтпелі жүруге тыйым"}, {"ru": "Только ночью", "kk": "Тек түнде"}, {"ru": "Да, всегда", "kk": "Иә, әрқашан"}], "correct": 0, "explain": {"ru": "Сквозной проезд через жилую зону запрещён.", "kk": "Тұрғын аймақ арқылы өтпелі жүруге тыйым."}}, {"id": "q_pdd_249", "q": {"ru": "Что означает знак «Конец жилой зоны»?", "kk": "«Тұрғын аймақтың соңы» белгісі нені білдіреді?"}, "options": [{"ru": "Парковка", "kk": "Тұрақ"}, {"ru": "Жилая зона заканчивается", "kk": "Тұрғын аймақ аяқталады"}, {"ru": "Начало зоны", "kk": "Аймақтың басы"}], "correct": 1, "explain": {"ru": "Отменяет правила жилой зоны.", "kk": "Тұрғын аймақ ережелерін жояды."}}, {"id": "q_pdd_250", "q": {"ru": "Как правильно перевозить негабаритный груз днём?", "kk": "Габаритсіз жүкті күндіз қалай дұрыс тасымалдау керек?"}, "options": [{"ru": "Со светоотражающими знаками и при необходимости разрешением", "kk": "Жарық шағылыстыратын белгілермен және қажет болса рұқсатпен"}, {"ru": "Без знаков", "kk": "Белгісіз"}, {"ru": "Только ночью", "kk": "Тек түнде"}], "correct": 0, "explain": {"ru": "Негабарит обозначают.", "kk": "Габаритсізді белгілейді."}}, {"id": "q_pdd_251", "q": {"ru": "Что грозит за непристёгнутый ремень?", "kk": "Байланбаған белдік үшін не күтеді?"}, "options": [{"ru": "Ничего", "kk": "Ештеңе"}, {"ru": "Штраф", "kk": "Айыппұл"}, {"ru": "Только предупреждение всегда", "kk": "Әрқашан тек ескерту"}], "correct": 1, "explain": {"ru": "Непристёгнутый ремень — штраф.", "kk": "Байланбаған белдік — айыппұл."}}, {"id": "q_pdd_252", "q": {"ru": "Можно ли перевозить пассажира на коленях?", "kk": "Жолаушыны тізеде тасымалдауға бола ма?"}, "options": [{"ru": "Только ребёнка", "kk": "Тек баланы"}, {"ru": "Да", "kk": "Иә"}, {"ru": "Нет", "kk": "Жоқ"}], "correct": 2, "explain": {"ru": "Перевозка на коленях запрещена.", "kk": "Тізеде тасымалдауға тыйым."}}, {"id": "q_pdd_253", "q": {"ru": "Что означает знак «Остановка запрещена» с табличкой времени?", "kk": "Уақыт тақтайшасы бар «Тоқтауға тыйым» белгісі нені білдіреді?"}, "options": [{"ru": "Запрет действует в указанное время", "kk": "Тыйым көрсетілген уақытта әрекет етеді"}, {"ru": "Никогда", "kk": "Ешқашан"}, {"ru": "Всегда", "kk": "Әрқашан"}], "correct": 0, "explain": {"ru": "Табличка ограничивает время действия.", "kk": "Тақтайша әрекет ету уақытын шектейді."}}, {"id": "q_pdd_254", "q": {"ru": "Как действовать при знаке «Конец зоны всех ограничений»?", "kk": "«Барлық шектеулер аймағының соңы» белгісінде қалай әрекет ету керек?"}, "options": [{"ru": "Стоп", "kk": "Тоқта"}, {"ru": "Начинаются новые", "kk": "Жаңалары басталады"}, {"ru": "Ограничения снимаются", "kk": "Шектеулер алынады"}], "correct": 2, "explain": {"ru": "Знак отменяет ограничения зоны.", "kk": "Белгі аймақ шектеулерін жояды."}}, {"id": "q_pdd_255", "q": {"ru": "Разрешена ли стоянка на месте для инвалидов без знака?", "kk": "Мүгедектер орнында белгісіз тұраққа рұқсат па?"}, "options": [{"ru": "Нет", "kk": "Жоқ"}, {"ru": "Только на 5 минут", "kk": "Тек 5 минут"}, {"ru": "Да", "kk": "Иә"}], "correct": 0, "explain": {"ru": "Места для инвалидов — только с разрешением.", "kk": "Мүгедектер орындары — тек рұқсатпен."}}, {"id": "q_pdd_256", "q": {"ru": "Что должен сделать водитель при приближении к школе?", "kk": "Мектепке жақындағанда жүргізуші не істеуі керек?"}, "options": [{"ru": "Ускориться", "kk": "Жылдамдау"}, {"ru": "Сигналить", "kk": "Сигнал беру"}, {"ru": "Снизить скорость и быть готовым к детям", "kk": "Жылдамдықты төмендетіп, балаларға дайын болу"}], "correct": 2, "explain": {"ru": "У школ — особая осторожность.", "kk": "Мектептерде — ерекше сақтық."}}, {"id": "q_pdd_257", "q": {"ru": "Можно ли обгонять школьный автобус с включённой аварийкой?", "kk": "Апат сигналы қосылған мектеп автобусын басып озуға бола ма?"}, "options": [{"ru": "Нет, пока дети садятся/выходят", "kk": "Жоқ, балалар отырған/түскен кезде"}, {"ru": "Да", "kk": "Иә"}, {"ru": "Только справа", "kk": "Тек оң жақтан"}], "correct": 0, "explain": {"ru": "У школьного автобуса с аварийкой нужно остановиться.", "kk": "Апат сигналы бар мектеп автобусында тоқтау керек."}}, {"id": "q_pdd_258", "q": {"ru": "Как правильно использовать противотуманные фары?", "kk": "Тұманға қарсы фараларды қалай дұрыс қолдану керек?"}, "options": [{"ru": "Никогда", "kk": "Ешқашан"}, {"ru": "Всегда", "kk": "Әрқашан"}, {"ru": "В туман, дождь, снег и где разрешено", "kk": "Тұман, жаңбыр, қарда және рұқсат етілген жерде"}], "correct": 2, "explain": {"ru": "Противотуманные — при плохой видимости.", "kk": "Тұманға қарсы — көріну нашар болғанда."}}, {"id": "q_pdd_259", "q": {"ru": "Что означает знак «Опасная обочина»?", "kk": "«Қауіпті жол жиегі» белгісі нені білдіреді?"}, "options": [{"ru": "Главная", "kk": "Басты"}, {"ru": "Обочина небезопасна для съезда", "kk": "Жол жиегі шығуға қауіпсіз емес"}, {"ru": "Парковка", "kk": "Тұрақ"}], "correct": 1, "explain": {"ru": "Предупреждает об опасной обочине.", "kk": "Қауіпті жол жиегі туралы ескертеді."}}, {"id": "q_pdd_260", "q": {"ru": "Как действовать на горной дороге при встречном разъезде?", "kk": "Тау жолында қарсы айырылыста қалай әрекет ету керек?"}, "options": [{"ru": "Кто быстрее", "kk": "Кім жылдам"}, {"ru": "Всегда нижний", "kk": "Әрқашан төменгі"}, {"ru": "Уступает тот, у кого препятствие со своей стороны / по правилам разъезда", "kk": "Өз жағында кедергісі бар / айырылыс ережесі бойынша жол береді"}], "correct": 2, "explain": {"ru": "На узкой дороге уступают по правилам.", "kk": "Тар жолда ереже бойынша жол береді."}}, {"id": "q_pdd_261", "q": {"ru": "Разрешена ли остановка в тоннеле?", "kk": "Туннельде тоқтауға рұқсат па?"}, "options": [{"ru": "Да", "kk": "Иә"}, {"ru": "Нет", "kk": "Жоқ"}, {"ru": "Только на 1 минуту", "kk": "Тек 1 минут"}], "correct": 1, "explain": {"ru": "Остановка в тоннеле запрещена.", "kk": "Туннельде тоқтауға тыйым."}}, {"id": "q_pdd_262", "q": {"ru": "Что означает знак «Направление главной дороги» (табличка)?", "kk": "«Басты жол бағыты» тақтайшасы нені білдіреді?"}, "options": [{"ru": "Конец главной", "kk": "Басты жолдың соңы"}, {"ru": "Уступите", "kk": "Жол беріңіз"}, {"ru": "Как проходит главная на перекрёстке", "kk": "Қиылыста басты жол қалай өтетіні"}], "correct": 2, "explain": {"ru": "Показывает трассировку главной.", "kk": "Басты жолдың бағытын көрсетеді."}}, {"id": "q_pdd_263", "q": {"ru": "Можно ли двигаться задним ходом на автомагистрали?", "kk": "Автомагистральда артқа жүруге бола ма?"}, "options": [{"ru": "Нет", "kk": "Жоқ"}, {"ru": "Только на обочине", "kk": "Тек жол жиегінде"}, {"ru": "Да", "kk": "Иә"}], "correct": 0, "explain": {"ru": "Задний ход на автомагистрали запрещён.", "kk": "Автомагистральда артқа жүруге тыйым."}}, {"id": "q_pdd_264", "q": {"ru": "Как правильно перестроиться в крайнюю полосу перед поворотом?", "kk": "Бұрылыс алдында ең шеткі жолаққа қалай дұрыс ауысу керек?"}, "options": [{"ru": "Без сигнала", "kk": "Сигналсыз"}, {"ru": "Заранее, с сигналом, уступив", "kk": "Алдын ала, сигналмен, жол беріп"}, {"ru": "В последний момент", "kk": "Соңғы сәтте"}], "correct": 1, "explain": {"ru": "Перестроение заранее.", "kk": "Қатар ауыстыру алдын ала."}}, {"id": "q_pdd_265", "q": {"ru": "Что грозит за проезд ж/д переезда на запрещающий сигнал?", "kk": "Тыйым салатын сигналға теміржол өткелін өткені үшін не күтеді?"}, "options": [{"ru": "Только предупреждение", "kk": "Тек ескерту"}, {"ru": "Ничего", "kk": "Ештеңе"}, {"ru": "Штраф и возможное лишение", "kk": "Айыппұл және құқықтан айыру мүмкін"}], "correct": 2, "explain": {"ru": "Проезд на запрещающий — серьёзное нарушение.", "kk": "Тыйым салатынға өту — ауыр бұзушылық."}}, {"id": "q_pdd_266", "q": {"ru": "Как действовать при заторе на кольце?", "kk": "Шеңберде кептеліс болса қалай әрекет ету керек?"}, "options": [{"ru": "Ехать по обочине", "kk": "Жол жиегімен жүру"}, {"ru": "Не въезжать, если не сможете выехать", "kk": "Шыға алмасаңыз кірмеу"}, {"ru": "Въезжать всё равно", "kk": "Бәрібір кіру"}], "correct": 1, "explain": {"ru": "Не создавать затор на кольце.", "kk": "Шеңберде кептеліс туғызбау."}}, {"id": "q_pdd_267", "q": {"ru": "Что означает знак «Обязательная остановка» (Стоп) в сочетании с «Таможня»?", "kk": "«Кеден» белгісімен бірге «Стоп» нені білдіреді?"}, "options": [{"ru": "Парковка", "kk": "Тұрақ"}, {"ru": "Можно проехать", "kk": "Өтуге болады"}, {"ru": "Остановка для контроля", "kk": "Бақылау үшін тоқтау"}], "correct": 2, "explain": {"ru": "Обязательная остановка на контроле.", "kk": "Бақылауда міндетті тоқтау."}}, {"id": "q_pdd_268", "q": {"ru": "Разрешена ли перевозка людей в кузове легкового прицепа?", "kk": "Жеңіл тіркеменің кузовында адам тасымалдауға рұқсат па?"}, "options": [{"ru": "Только одного", "kk": "Тек біреуді"}, {"ru": "Нет", "kk": "Жоқ"}, {"ru": "Да", "kk": "Иә"}], "correct": 1, "explain": {"ru": "В легковом прицепе людей возить нельзя.", "kk": "Жеңіл тіркемеде адам тасымалдауға болмайды."}}, {"id": "q_pdd_269", "q": {"ru": "Что должен сделать водитель при смене полосы?", "kk": "Жолақ ауыстырғанда жүргізуші не істеуі керек?"}, "options": [{"ru": "Просто выехать", "kk": "Жай шығу"}, {"ru": "Сигналить", "kk": "Сигнал беру"}, {"ru": "Включить сигнал и уступить тем, кто уже на полосе", "kk": "Сигнал қосып, жолақтағыларға жол беру"}], "correct": 2, "explain": {"ru": "Перестроение с сигналом и уступкой.", "kk": "Сигналмен және жол берумен қатар ауыстыру."}}, {"id": "q_pdd_270", "q": {"ru": "Как действовать при гололедице на мосту?", "kk": "Көпірде көктайғақта қалай әрекет ету керек?"}, "options": [{"ru": "Как обычно", "kk": "Әдеттегідей"}, {"ru": "Ещё осторожнее: мосты обледеневают раньше", "kk": "Одан да сақтықпен: көпірлер ертерек мұз тартады"}, {"ru": "Ускориться", "kk": "Жылдамдау"}], "correct": 1, "explain": {"ru": "Мосты опаснее в гололёд.", "kk": "Көктайғақта көпірлер қауіптірек."}}, {"id": "q_pdd_271", "q": {"ru": "Что означает знак «Велосипедное движение запрещено»?", "kk": "«Велосипед қозғалысы тыйым» белгісі нені білдіреді?"}, "options": [{"ru": "Велосипедистам нельзя", "kk": "Велосипедшілерге болмайды"}, {"ru": "Только пешеходам", "kk": "Тек жаяу жүргіншілерге"}, {"ru": "Всем нельзя", "kk": "Барлығына болмайды"}], "correct": 0, "explain": {"ru": "Запрещает движение велосипедов.", "kk": "Велосипед қозғалысына тыйым салады."}}, {"id": "q_pdd_272", "q": {"ru": "Можно ли парковаться вторым рядом?", "kk": "Екінші қатарға тұраққа қоюға бола ма?"}, "options": [{"ru": "Да", "kk": "Иә"}, {"ru": "Нет", "kk": "Жоқ"}, {"ru": "Только на 5 минут", "kk": "Тек 5 минут"}], "correct": 1, "explain": {"ru": "Стоянка вторым рядом запрещена.", "kk": "Екінші қатарға тұраққа тыйым."}}, {"id": "q_pdd_273", "q": {"ru": "Что означает знак «Разворот запрещён»?", "kk": "«Бұрылуға тыйым» белгісі нені білдіреді?"}, "options": [{"ru": "Обгон запрещён", "kk": "Басып озуға тыйым"}, {"ru": "Поворот налево запрещён тоже всегда", "kk": "Солға бұрылыс та әрқашан тыйым"}, {"ru": "Разворот запрещён", "kk": "Бұрылуға тыйым"}], "correct": 2, "explain": {"ru": "Запрещает именно разворот.", "kk": "Нақты бұрылуға тыйым салады."}}, {"id": "q_pdd_274", "q": {"ru": "Как действовать при знаке «Движение с прицепом запрещено»?", "kk": "«Тіркемемен қозғалыс тыйым» белгісінде қалай әрекет ету керек?"}, "options": [{"ru": "Только ночью", "kk": "Тек түнде"}, {"ru": "С прицепом нельзя", "kk": "Тіркемемен болмайды"}, {"ru": "Всем нельзя", "kk": "Барлығына болмайды"}], "correct": 1, "explain": {"ru": "Запрещает ТС с прицепом.", "kk": "Тіркемелі көліктерге тыйым салады."}}, {"id": "q_pdd_275", "q": {"ru": "Что грозит за выезд на встречную через сплошную?", "kk": "Тұтас сызық арқылы қарсы жолаққа шыққаны үшін не күтеді?"}, "options": [{"ru": "Ничего", "kk": "Ештеңе"}, {"ru": "Только предупреждение", "kk": "Тек ескерту"}, {"ru": "Штраф, возможное лишение", "kk": "Айыппұл, құқықтан айыру мүмкін"}], "correct": 2, "explain": {"ru": "Выезд на встречную — серьёзное нарушение.", "kk": "Қарсы жолаққа шығу — ауыр бұзушылық."}}, {"id": "q_pdd_276", "q": {"ru": "Как правильно включить дальний свет?", "kk": "Алыс жарықты қалай дұрыс қосу керек?"}, "options": [{"ru": "Всегда в городе", "kk": "Қалада әрқашан"}, {"ru": "Вне города при отсутствии встречных и впереди идущих близко", "kk": "Қала сыртында қарсы келетіндер және жақын алдағылар болмағанда"}, {"ru": "В туннеле всегда дальний", "kk": "Туннельде әрқашан алыс"}], "correct": 1, "explain": {"ru": "Дальний — когда никого не слепит.", "kk": "Алыс жарық — ешкімді соқыр етпегенде."}}, {"id": "q_pdd_277", "q": {"ru": "Что делать, если встречный не переключился на ближний?", "kk": "Қарсы келетін жақын жарыққа ауыспаса не істеу керек?"}, "options": [{"ru": "Остановиться посреди дороги", "kk": "Жол ортасында тоқтау"}, {"ru": "Тоже держать дальний", "kk": "Да алысты ұстау"}, {"ru": "Кратко моргнуть и при ослеплении снизить скорость", "kk": "Қысқа жыпылықтатып, соқыр етсе жылдамдықты төмендету"}], "correct": 2, "explain": {"ru": "Не отвечать дальним длительно.", "kk": "Алыспен ұзақ жауап бермеу."}}, {"id": "q_pdd_278", "q": {"ru": "Разрешена ли остановка на полосе разгона?", "kk": "Үдеу жолағында тоқтауға рұқсат па?"}, "options": [{"ru": "Только ночью", "kk": "Тек түнде"}, {"ru": "Нет", "kk": "Жоқ"}, {"ru": "Да", "kk": "Иә"}], "correct": 1, "explain": {"ru": "На полосе разгона остановка запрещена.", "kk": "Үдеу жолағында тоқтауға тыйым."}}, {"id": "q_pdd_279", "q": {"ru": "Как влиться в поток с полосы разгона?", "kk": "Үдеу жолағынан ағынға қалай қосылу керек?"}, "options": [{"ru": "Иметь преимущество", "kk": "Басымдыққа ие болу"}, {"ru": "Остановиться и ждать пустоты всегда", "kk": "Әрқашан тоқтап, бостықты күту"}, {"ru": "Уступить движущимся по основной и встроиться", "kk": "Негізгі жолмен жүріп жатқандарға жол беріп, кірігу"}], "correct": 2, "explain": {"ru": "С полосы разгона уступают основному потоку.", "kk": "Үдеу жолағынан негізгі ағынға жол береді."}}, {"id": "q_pdd_280", "q": {"ru": "Что означает знак «Полоса для маршрутных ТС»?", "kk": "«Бағыттық көліктер жолағы» белгісі нені білдіреді?"}, "options": [{"ru": "Полоса для автобусов", "kk": "Автобус жолағы"}, {"ru": "Парковка", "kk": "Тұрақ"}, {"ru": "Для всех", "kk": "Барлығына"}], "correct": 0, "explain": {"ru": "Выделенная полоса для маршрутных.", "kk": "Бағыттық көліктерге арналған жолақ."}}, {"id": "q_pdd_281", "q": {"ru": "Можно ли выезжать на автобусную полосу для поворота направо?", "kk": "Оңға бұрылу үшін автобус жолағына шығуға бола ма?"}, "options": [{"ru": "Только ночью", "kk": "Тек түнде"}, {"ru": "Никогда", "kk": "Ешқашан"}, {"ru": "Да, если это необходимо для поворота и не запрещено", "kk": "Иә, бұрылу үшін қажет болса және тыйым салынбаса"}], "correct": 2, "explain": {"ru": "Для поворота часто разрешён краткий выезд.", "kk": "Бұрылу үшін қысқа шығу жиі рұқсат."}}, {"id": "q_pdd_282", "q": {"ru": "Что обязан сделать водитель при дорожно-транспортном происшествии без пострадавших?", "kk": "Зардап шеккендерсіз ЖКО кезінде жүргізуші не істеуге міндетті?"}, "options": [{"ru": "Оформить по правилам (европротокол или полиция)", "kk": "Ереже бойынша ресімдеу (еуропротокол немесе полиция)"}, {"ru": "Уехать", "kk": "Кетіп қалу"}, {"ru": "Только договориться устно", "kk": "Тек ауызша келісу"}], "correct": 0, "explain": {"ru": "ДТП нужно оформить.", "kk": "ЖКО-ны ресімдеу керек."}}, {"id": "q_pdd_283", "q": {"ru": "Как действовать при сильном снегопаде?", "kk": "Қатты қар жауғанда қалай әрекет ету керек?"}, "options": [{"ru": "Выключить свет", "kk": "Жарықты өшіру"}, {"ru": "Ехать как летом", "kk": "Жаздағыдай жүру"}, {"ru": "Снизить скорость, увеличить дистанцию, включить свет", "kk": "Жылдамдықты төмендетіп, арақашықтықты ұлғайтып, жарықты қосу"}], "correct": 2, "explain": {"ru": "В снег — осторожность.", "kk": "Қарда — сақтық."}}, {"id": "q_pdd_284", "q": {"ru": "Что означает знак «Ограничение максимальной скорости» в красном круге 40 у школы?", "kk": "Мектеп жанындағы қызыл шеңбердегі 40 «ең жоғары жылдамдық» белгісі нені білдіреді?"}, "options": [{"ru": "Не быстрее 40", "kk": "40-тан жылдам емес"}, {"ru": "Минимум 40", "kk": "Ең кемі 40"}, {"ru": "Рекомендация", "kk": "Ұсыныс"}], "correct": 0, "explain": {"ru": "Обязательный лимит 40.", "kk": "40 міндетті шек."}}, {"id": "q_pdd_285", "q": {"ru": "Разрешена ли стоянка с работающим двигателем во дворе ночью?", "kk": "Түнде аулада қозғалтқышы жұмыс істеп тұрған тұраққа рұқсат па?"}, "options": [{"ru": "Только 30 минут", "kk": "Тек 30 минут"}, {"ru": "Да", "kk": "Иә"}, {"ru": "Нет, мешает жителям", "kk": "Жоқ, тұрғындарға кедергі"}], "correct": 2, "explain": {"ru": "Прогрев и стоянка с двигателем во дворе нежелательны и часто запрещены.", "kk": "Аулада қозғалтқышпен тұрақ ұсынылмайды және жиі тыйым."}}, {"id": "q_pdd_286", "q": {"ru": "Что должен знать кандидат в водители о знаке «Учебное ТС»?", "kk": "Жүргізуші үміткері «Оқу көлігі» белгісі туралы не білуі керек?"}, "options": [{"ru": "Его нужно включать на учебной машине", "kk": "Оны оқу көлігінде қосу керек"}, {"ru": "Он не нужен", "kk": "Ол қажет емес"}, {"ru": "Только ночью", "kk": "Тек түнде"}], "correct": 0, "explain": {"ru": "Учебное авто обозначают.", "kk": "Оқу көлігін белгілейді."}}, {"id": "q_pdd_287", "q": {"ru": "Как действовать на перекрёстке, если вы на второстепенной, а справа тоже второстепенная?", "kk": "Сіз қосалқыда, оң жақта да қосалқы болса қиылыста қалай әрекет ету керек?"}, "options": [{"ru": "Всегда стоп на 3 минуты", "kk": "Әрқашан 3 минут тоқта"}, {"ru": "Ехать первым", "kk": "Бірінші жүру"}, {"ru": "Уступить помехе справа среди второстепенных, но сначала главной", "kk": "Алдымен бастыға, содан қосалқылар арасында оң кедергіге жол беру"}], "correct": 2, "explain": {"ru": "Сначала уступают главной, затем помехе справа.", "kk": "Алдымен бастыға, содан оң кедергіге жол береді."}}, {"id": "q_pdd_288", "q": {"ru": "Что означает белая стрелка на синем фоне «выезд на дорогу с односторонним»?", "kk": "Көк фонда ақ жебе «бір бағытты жолға шығу» нені білдіреді?"}, "options": [{"ru": "Выезд на одностороннюю в указанном направлении", "kk": "Көрсетілген бағытта бір бағыттыға шығу"}, {"ru": "Тупик", "kk": "Тұйық"}, {"ru": "Двустороннее", "kk": "Екі бағытты"}], "correct": 0, "explain": {"ru": "Информирует о выезде на одностороннюю.", "kk": "Бір бағыттыға шығу туралы хабарлайды."}}, {"id": "q_pdd_289", "q": {"ru": "Можно ли разворачиваться через двойную сплошную?", "kk": "Қос тұтас сызық арқылы бұрылуға бола ма?"}, "options": [{"ru": "Только если нет машин", "kk": "Тек көлік болмаса"}, {"ru": "Да", "kk": "Иә"}, {"ru": "Нет", "kk": "Жоқ"}], "correct": 2, "explain": {"ru": "Через двойную сплошную нельзя.", "kk": "Қос тұтас арқылы болмайды."}}, {"id": "q_pdd_290", "q": {"ru": "Как правильно пропустить пешехода на нерегулируемом переходе ночью?", "kk": "Түнде реттелмейтін өткелде жаяу жүргіншіні қалай дұрыс өткізу керек?"}, "options": [{"ru": "Заранее снизить скорость и остановиться", "kk": "Алдын ала жылдамдықты төмендетіп, тоқтау"}, {"ru": "Не замечать", "kk": "Байқамау"}, {"ru": "Сигналить и ехать", "kk": "Сигнал беріп, жүру"}], "correct": 0, "explain": {"ru": "Ночью пешехода видно хуже — нужна осторожность.", "kk": "Түнде жаяу жүргінші нашар көрінеді — сақтық керек."}}, {"id": "q_pdd_291", "q": {"ru": "Что грозит за управление в состоянии опьянения в РК?", "kk": "ҚР-да мас күйде басқарғаны үшін не күтеді?"}, "options": [{"ru": "Ничего", "kk": "Ештеңе"}, {"ru": "Штраф, лишение прав, возможный арест", "kk": "Айыппұл, құқықтан айыру, қамау мүмкін"}, {"ru": "Только штраф всегда", "kk": "Әрқашан тек айыппұл"}], "correct": 1, "explain": {"ru": "Нетрезвое вождение строго наказывается.", "kk": "Мас күйде жүргізу қатаң жазаланады."}}, {"id": "q_pdd_292", "q": {"ru": "Как действовать при отказе рулевого управления?", "kk": "Рөлдік басқару істен шыққанда қалай әрекет ету керек?"}, "options": [{"ru": "Продолжать", "kk": "Жалғастыру"}, {"ru": "Газовать", "kk": "Газ беру"}, {"ru": "Плавно остановиться, аварийка, знак", "kk": "Жұмсақ тоқтап, апат сигналы, белгі"}], "correct": 2, "explain": {"ru": "При отказе руля — безопасная остановка.", "kk": "Рөл істен шыққанда — қауіпсіз тоқтау."}}, {"id": "q_pdd_293", "q": {"ru": "Что означает знак «Конец ограничения максимальной скорости» 60?", "kk": "60 «ең жоғары жылдамдық шектеуінің соңы» белгісі нені білдіреді?"}, "options": [{"ru": "Лимит 60 снимается", "kk": "60 шегі алынады"}, {"ru": "Начинается 60", "kk": "60 басталады"}, {"ru": "Минимум 60", "kk": "Ең кемі 60"}], "correct": 0, "explain": {"ru": "Отменяет ограничение 60.", "kk": "60 шектеуін жояды."}}, {"id": "q_pdd_294", "q": {"ru": "Разрешена ли остановка на проезжей части односторонней дороги у левого края?", "kk": "Бір бағытты жолдың жүру бөлігінде сол жиекте тоқтауға рұқсат па?"}, "options": [{"ru": "Никогда", "kk": "Ешқашан"}, {"ru": "Да, если не запрещено", "kk": "Иә, тыйым салынбаса"}, {"ru": "Только грузовикам", "kk": "Тек жүк көліктеріне"}], "correct": 1, "explain": {"ru": "На односторонней можно у левого края, если нет запрета.", "kk": "Бір бағыттыда тыйым болмаса сол жиекте болады."}}, {"id": "q_pdd_295", "q": {"ru": "Как действовать при знаке «Обгон запрещён» и прерывистой разметке?", "kk": "«Басып озуға тыйым» белгісі және үзік белгілеуде қалай әрекет ету керек?"}, "options": [{"ru": "Знак главнее — обгон запрещён", "kk": "Белгі басым — басып озуға тыйым"}, {"ru": "Разметка разрешает", "kk": "Белгілеу рұқсат етеді"}, {"ru": "Как хочешь", "kk": "Қалағаныңша"}], "correct": 0, "explain": {"ru": "Знак запрета обгона действует независимо от прерывистой.", "kk": "Басып озуға тыйым белгісі үзік сызыққа қарамастан әрекет етеді."}}, {"id": "q_pdd_296", "q": {"ru": "Что должен сделать водитель при посадке пассажира?", "kk": "Жолаушы отырғызғанда жүргізуші не істеуі керек?"}, "options": [{"ru": "На переходе", "kk": "Өткелде"}, {"ru": "Остановиться у края, не мешая", "kk": "Жиекте тоқтап, кедергісіз"}, {"ru": "Посреди полосы", "kk": "Жолақ ортасында"}], "correct": 1, "explain": {"ru": "Посадка — у края проезжей части.", "kk": "Отырғызу — жүру бөлігінің жиегінде."}}, {"id": "q_pdd_297", "q": {"ru": "Можно ли использовать дальний свет в населённом пункте?", "kk": "Елді мекенде алыс жарықты қолдануға бола ма?"}, "options": [{"ru": "Нет, кроме случаев, когда дорога не освещена и нет встречных", "kk": "Жоқ, жол жарықтанбаған және қарсы келетіндер болмаған жағдайдан басқа"}, {"ru": "Да, всегда", "kk": "Иә, әрқашан"}, {"ru": "Только в дождь", "kk": "Тек жаңбырда"}], "correct": 0, "explain": {"ru": "В городе дальний почти не используют.", "kk": "Қалада алыс жарықты дерлік қолданбайды."}}, {"id": "q_pdd_298", "q": {"ru": "Что означает знак «Примыкание второстепенной дороги»?", "kk": "«Қосалқы жолдың қосылуы» белгісі нені білдіреді?"}, "options": [{"ru": "Вы на второстепенной", "kk": "Сіз қосалқыдасыз"}, {"ru": "Сбоку примыкает второстепенная", "kk": "Бүйірден қосалқы қосылады"}, {"ru": "Тупик", "kk": "Тұйық"}], "correct": 1, "explain": {"ru": "Предупреждает о примыкании.", "kk": "Қосылу туралы ескертеді."}}, {"id": "q_pdd_299", "q": {"ru": "Как действовать на узком мосту при встречном разъезде?", "kk": "Тар көпірде қарсы айырылыста қалай әрекет ету керек?"}, "options": [{"ru": "Кто ближе к мосту, тот и едет, либо по знакам", "kk": "Көпірге жақын немесе белгілер бойынша"}, {"ru": "Ехать вместе", "kk": "Бірге жүру"}, {"ru": "Всегда ждать", "kk": "Әрқашан күту"}], "correct": 0, "explain": {"ru": "На узком участке уступают по ситуации и знакам.", "kk": "Тар учаскеде жағдай мен белгілер бойынша жол береді."}}, {"id": "q_pdd_300", "q": {"ru": "Разрешена ли учебная езда по дорогам общего пользования?", "kk": "Жалпы пайдаланудағы жолдарда оқу жүрісіне рұқсат па?"}, "options": [{"ru": "Только ночью", "kk": "Тек түнде"}, {"ru": "Да, с инструктором и обозначением", "kk": "Иә, нұсқаушымен және белгілеумен"}, {"ru": "Нет", "kk": "Жоқ"}], "correct": 1, "explain": {"ru": "Учебная езда разрешена при соблюдении условий.", "kk": "Оқу жүрісі шарттар сақталса рұқсат."}}, {"id": "q_pdd_301", "q": {"ru": "Что грозит за неостановку по требованию полиции?", "kk": "Полиция талабы бойынша тоқтамағаны үшін не күтеді?"}, "options": [{"ru": "Только устное замечание", "kk": "Тек ауызша ескерту"}, {"ru": "Ничего", "kk": "Ештеңе"}, {"ru": "Штраф и возможное задержание", "kk": "Айыппұл және ұстау мүмкін"}], "correct": 2, "explain": {"ru": "Неостановка по требованию — нарушение.", "kk": "Талап бойынша тоқтамау — бұзушылық."}}, {"id": "q_pdd_302", "q": {"ru": "Как правильно хранить огнетушитель и аптечку?", "kk": "Өрт сөндіргіш пен дәрі қобдишасын қалай дұрыс сақтау керек?"}, "options": [{"ru": "В доступном месте, годные", "kk": "Қолжетімді жерде, жарамды"}, {"ru": "Не нужны", "kk": "Қажет емес"}, {"ru": "В багажнике недоступно", "kk": "Жүксалғышта қолжетімсіз"}], "correct": 0, "explain": {"ru": "Аптечка и огнетушитель должны быть 